const env = (name: string) => (process.env[name] || "").trim();

export const CUSTOMER_SERVICE = {
  whatsapp: env("REACT_APP_CUSTOMER_SERVICE_WHATSAPP") || "2348000000000",
  phone: env("REACT_APP_CUSTOMER_SERVICE_PHONE") || "+234 800 000 0000",
  email: env("REACT_APP_CUSTOMER_SERVICE_EMAIL") || "support@fishlink.ng",
  hours:
    env("REACT_APP_CUSTOMER_SERVICE_HOURS") || "Mon-Sat, 8:00-18:00 WAT",
  isDemo:
    !env("REACT_APP_CUSTOMER_SERVICE_WHATSAPP") &&
    !env("REACT_APP_CUSTOMER_SERVICE_PHONE"),
};

const digitsOnly = (value: string) => value.replace(/\D/g, "");

export const normaliseWhatsAppNumber = (value: string): string => {
  const digits = digitsOnly(value);

  if (digits.startsWith("00")) return digits.slice(2);
  if (digits.startsWith("0") && digits.length === 11) {
    return `234${digits.slice(1)}`;
  }

  return digits;
};

export const isWhatsAppNumber = (value: string): boolean =>
  normaliseWhatsAppNumber(value).length >= 10;

export const whatsappUrl = (phone: string, message: string): string =>
  `https://wa.me/${normaliseWhatsAppNumber(phone)}?text=${encodeURIComponent(
    message
  )}`;
